  },
  unmounted: function () {
    window.removeEventListener('resize', this.windowResize);
    document.removeEventListener('new_log', this.addNewLog);
  },
  methods: {
    async init() {
      this.isSecondApproval();
      if (!this.$route.params.id) {
        this.$router.push('/dashboard');
      }

      if (this.second_approval) {
        this.filter_status = 'approved_pending_second_approval';
      }

      this.docId = this.$route.params.id as string;

      this.initRequiredFields();
      await this.getInvoiceDataByDocId(this.docId);

      this.renderDocumentLog();
      this.renderPendingRecordsCountView();
      this.renderNextPrevLinkBtns();

      await this.makeReadOnlyModel();
      await this.makeEditableModel();

      this.getAssignToUsers();

      if (readOnlyDocStatus.includes(this.record.status)) {
        this.isReadOnly = true;
      }

      this.handleImageBaseURL();
      this.image =
        this.baseUrl + '/' + cleanUpImagePath(this.record.images[0].path);
      this.images = cleanUpImagesUrl(this.record.images);
      logInfo(this.images);

      // set the width of image
      let imageElm = $('#image_container') as HTMLElement;
      this.imageWidth = imageElm.offsetWidth;
      this.imageHeight = imageElm.offsetHeight;
      this.getImageDetails();
    },
    sortStampsByLanguage() {
      let lang = this.$i18n.language;
      let sorted: any = [];
      if (lang == DEFAULT_LANGUAGE) {
        lang = 'en';
      }
      this.stamps.forEach((stamp: string) => {
        if (lang != 'de' && lang != 'en') {
          lang = 'en';
        }
        if (stamp.includes(lang)) {
          sorted.push(stamp);
        }
      });
      this.selectedStamp = sorted[0];
      this.sortedStamps = sorted;
    },
    isSecondApproval() {
      if (
        this.$route.params.second_approval &&
        this.$route.params.second_approval === 'true'
      ) {
        this.second_approval = true;
      }
    },

    // TODO::Permission  acls needs to be applied here
    async getInvoiceDataByDocId(docId: string) {
      try {
        await this.getDocumentById(docId);
        if (!this.record.doc_id) {
          throw { message: 'INVALID_DOCUMENT' };
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    initRequiredFields() {
      this.readonly_model_required_fields.forEach(
        (field_name: any, index: any) => {
          let field_model = this.createEmptyField(field_name, 'text');

          this.readonlyModel[field_name] = field_model;
        },
      );

      this.model_required_fields.forEach((field_name: any, index: any) => {
        this.model[field_name] = '';
      });
    },

    makeReadOnlyModel() {
      return new Promise((resolve, reject) => {
        let data: any = {};
        if (this.record !== undefined) {
          this.record.fields.forEach((value: any, index: any) => {
            data[value.name] = value;
          });
          let layout = [] as dynamicObj[];
          layout = this.record.layout.groups;
          layout.forEach((group: any, index: any) => {
            group.rows.forEach((row: any, index: any) => {
              row.forEach((fieldDef: any, index: any) => {
                let field_name = fieldDef.field_name;
                let field_model = data[field_name];

                if (!field_model) {
                  field_model = this.createEmptyField(
                    field_name,
                    fieldDef.input_type,
                  );
                }

                this.readonlyModel[field_name] = field_model;
                this.readOnlyfieldsDef[field_name] = fieldDef;
              });
            });
          });
        }
        resolve('done');
      });
    },
    makeEditableModel() {
      return new Promise((resolve, reject) => {
        if (this.record !== undefined) {
          for (const [field_name, value] of Object.entries(this.record)) {
            this.model[field_name] = value;
          }
          this.setPrevAssignee();
        }
        resolve('done');
      });
    },
    setPrevAssignee() {
      this.prev_assignee = this.record.assigned_to;
    },
    createEmptyField(name: string, type: string) {
      let value = type == 'checkbox' ? false : '';
      return {
        confidence: 0,
        name: name,
        value: value,
        formatted_value: value,
        content: value,
      };
    },
    async getAssignToUsers() {
      await this.dropdownStore.prepareUsersDropdown();
      this.usersList = this.dropdownStore.usersList;
      this.model['assigned_to'] = this.getUserFullName(this.record.assigned_to);
      this.setPreviousApprover();
    },

    setPreviousApprover() {
      if (!this.second_approval) {
        return;
      }

      if (this.record.first_approver) {
        this.model['first_approver'] = this.getUserFullName(
          this.record.first_approver,
        );
      }
    },

    filterUserList(val: string, update: any, abort: any) {
      try {
        if (val === '') {
          update(() => {
            this.usersList = this.dropdownStore.usersList;
          });
          return;
        }

        update(() => {
          const needle = val.toLowerCase();
          this.usersList = this.dropdownStore.usersList.filter(
            (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
          );
        });
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        abort();
      }
    },
    getUserFullName(id: number) {
      let userInfo = this.dropdownStore.usersList.filter((v: any) => {
        return v.value == id;
      });

       
      return userInfo[0].label;
    },
    isModelReady() {
      return objLen(this.model) !== 0;
    },
    goHelp() {
      window.open('https://docs.cloudintegration.eu/');
    },
    inputValueChanges(field_name: string, new_value: any) {
      try {
        this.record[field_name] = new_value;
      } catch (err) {
        logError(err);
      }
    },
    setApiData(data: any) {
      this.record = data;
      this.$forceUpdate();
    },

    windowResize() {
      let imageElm = $('#image_container') as HTMLElement;
      this.imageWidth = imageElm.offsetWidth;
      this.imageHeight = imageElm.offsetHeight;
      this.$forceUpdate();

      setTimeout(() => {
        this.getImageDetails();
      }, 20);
    },
    getImageDetails() {
      screenshot = $('#screenshot') as HTMLElement;
      if (screenshot) {
        this.imageWidth = screenshot.offsetWidth;
        this.imageHeight = screenshot.offsetHeight;
      }
    },

    currentPage() {
      return this.page;
    },
    prevImage() {
      let new_page_number = this.page - 1;
      let path = this.getImagePath(new_page_number);
      this.updateImage(new_page_number, path);
    },

    nextImage() {
      let new_page_number = this.page + 1;
      let path = this.getImagePath(new_page_number);
      this.updateImage(new_page_number, path);
    },

    getImagePath(page_number: number) {
      let path = '';
      for (const [key, image] of Object.entries(this.images)) {
        let imageInfo = image as dynamicObj;
        if (imageInfo.pageNumber === page_number) {
          path = imageInfo.path;
        }
      }

      logInfo(path);
      return path;
    },

    updateImage(page_number: number, path: string) {
      if (!path || path === '') {
        return;
      }
      this.image = this.baseUrl + '/' + cleanUpImagePath(path);
      logInfo(this.image);
      this.page = page_number;
    },
    handleImageBaseURL() {
      if (!this.record.images[0]) {
        return;
      }
      if (this.record.images[0].path.match(/doc2/g)) {
        this.baseUrl = DOC2API_URL;
      }
    },
    updateApiData(e: any) {
      if (!e.detail) {
        return;
      }
      this.record = e.detail;
    },
    // TODO::Permission  acls needs to be applied here
    async saveData() {
      try {
        if (this.isReadOnly) {
          return;
        }
        if (!this.validateData()) {
          return;
        }

        this.showLoading();
        const response = await this.saveDocument(this.docId);
        if (response.success === false) {
          throw response;
        }

        notify.success(this.$t('MSG_SAVE'));
        this.setPrevAssignee();
        this.assign_user_error = false;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    validateData() {
      let validate = true;
      if (isUndefinedOrNull(this.record.assigned_to)) {
        this.assign_user_error = true;
        validate = false;
      }
      return validate;
    },

    // TODO::Permission  acls needs to be applied here
    acceptRequest() {
      let new_page_number = this.images.length;
      let path = this.getImagePath(new_page_number);
      this.updateImage(new_page_number, path);
      if (this.page === this.images.length) {
        let stamp_name =
          this.locale === 'de'
            ? 'approved_stamp_de'
            : ('approved_stamp_en' as string);
        (this.$refs.child_comp as any).addStampAnnotation(stamp_name);
      }
      this.record.first_approver = this.record.assigned_to;
      this.updateRequest('approve');
    },
    // TODO::Permission  acls needs to be applied here
    rejectRequest() {
      if (!this.second_approval) {
        delete this.record.first_approver;
      }

      this.updateRequest('reject');
    },

    async updateRequest(request_type: string) {
      try {
        if (this.isReadOnly) {
          return;
        }

        await this.saveData();
        this.showLoading();
        let formData = new FormData();
        const org_id = getOrgId();
        formData.append('request_type', request_type);
        formData.append('org_id', org_id);

        let response: any;
        let token: string = await getAuthorizationToken();
        response = await axios.post(
          api.approve_or_reject_document + this.docId,
          formData,
          {
            headers: {
              Authorization: token,
            },
          },
        );

        if (response.data.success === false) {
          throw response;
        }

        notify.success(this.$t('MSG_SAVE'));
        this.$router.push('/dashboard');
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    verifyAssignee() {
      let saved = true;
      if (this.prev_assignee !== this.record.assigned_to) {
        saved = false;
      }

      return saved;
    },
    addNewLog(e: any) {
      if (!e || !e.detail) {
        return;
      }

      this.renderDocumentLog();
      // let new_log = e.detail;
      // new_log.created_by_name = this.getUserFullName(new_log.created_by);

      // logInfo(new_log);
      // this.doc_logs[new_log.id.toString() + '_ID' ] = new_log;
    },
    async renderDocumentLog() {
      try {
        await this.getDocumentLogs();
      } catch (err) {
        logError('something went wrong while loading document logs');
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    async getDocumentLogs() {
      let response: any;
      this.doc_logs = {};
      let formData = new FormData();
      formData.append('action_type', 'message');
      formData.append('org_id', getOrgId());
      let token: string = await getAuthorizationToken();
      response = await axios.post(api.get_document_log + this.docId, formData, {
        headers: {
          Authorization: token,
        },
      });

      if (!response.data) {
        throw { message: 'no logs from server' };
      }

      response.data.forEach((row: any) => {
        this.doc_logs[row.id.toString() + '_ID'] = row;
      });
    },
    downloadFile() {
      downloadDocumentFile(this.docId, this.record.filename, this.tokenQueryParam, '.pdf');
    },
    routeToListPendingApproval() {
      this.removeDashboardFilters();
      // this.savedDashboardFilters('?filter=current-year&skip=0&limit=10&status=' + this.filter_status)
      this.$router.push('/dashboard');
    },
    async renderPendingRecordsCountView() {
      try {
        let response: any;
        let queryParams =
          '?filter=current-year&skip=0&limit=100&status=' + this.filter_status;
        let token: string = await getAuthorizationToken();

        response = await axios.get(
          addOrgIdQueryString(api.get_dashboard_data + queryParams),
          {
            headers: {
              Authorization: token,
            },
          },
        );
        if (!response.data.documents) {
          throw { message: 'no pending documents from server' };
        }

        this.pending_approval_doc_count = response.data.documents.length;
        if (this.pending_approval_doc_count < 0) {
          this.pending_approval_doc_count = 0;
        }
      } catch (err) {
        logError('something went wrong while loading document logs');
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    async renderNextPrevLinkBtns() {
      try {
        let response: any;
        let token: string = await getAuthorizationToken();
        response = await axios.get(
          addOrgIdQueryString(
            api.get_next_document +
              this.docId +
              '?doc_type=' +
              this.record.doc_type +
              '&status=' +
              this.filter_status +
              '&sort_attr=created_on',
          ),
          {
            headers: {
              Authorization: token,
            },
          },
        );
        if (response.data.success === false) {
          throw {
            message: 'cannot get response related to next or prev record',
          };
        }

        if (response.data.has_next && response.data.next_id) {
          this.next_record = response.data.next_id;
        }

        if (response.data.has_previous && response.data.previous_id) {
          this.prev_record = response.data.previous_id;
        }
      } catch (err) {
        logError('something went wrong while loading document logs');
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    checkValidStatus() {
      if (this.doc_status !== this.filter_status) {
        this.error = true;
        this.error_message = 'invalid_status';
      }
    },

    routeTo(direction: string) {
      let route = 'ready-for-approval';
      if (this.second_approval) {
        route = 'ready-for-second-approval';
      }

      if (direction === 'prev' && this.prev_record) {
        this.$router.push({
          path: '/' + route + '/' + this.prev_record,
          replace: true,
        });
      }

      if (direction === 'next' && this.next_record) {
        this.$router.push('/' + route + '/' + this.next_record);
      }
    },

    updateValue(key: any, value: any) {
      if (key == 'font') {
        this.selectFont = value;
      } else if (key == 'color') {
        this.selectColor = value;
      } else if (key == 'size') {
        this.selectFontSize = value;
      }
    },

    stampAddClicked() {
      (this.$refs.child_comp as any).addTemplateAnnotation(this.selectedStamp);
    },
  },
  setup() {
    const $q = useQuasar();
    let fieldsObjArray: any = {};
    let data: any = [];
    const dropdownStore = useDropdownStore();
    const { getSelectedLanguage } = dropdownStore;

    const tolgee = useTolgee(['language']);
    const locale = computed(() => tolgee.value.getLanguage() || 'en');

    const doc_store = useDocumentStore();
    const { getDocumentById, getDocAnnotations, saveDocument } = doc_store;
    const { record, doc_status, error, error_message, page } =
      storeToRefs(doc_store);

    const dashboard_store = useDashboardStore();
    const {
      removeSavedFilters: removeDashboardFilters,
      saveFilters: savedDashboardFilters,
    } = dashboard_store;

    const { tokenQueryParam, refreshTokenParam } = useImageAuth();
    return {
      locale,
      saveDocument,
      tokenQueryParam,
      getSelectedLanguage,
      savedDashboardFilters,
      removeDashboardFilters,
      doc_status,
      page,
      error,
      error_message,
      getDocumentById,
      record,
      dropdownStore,
      fields: fieldsObjArray,
      image: '',
      images: data,
      baseUrl: DOC2API_URL,
      isReadOnly: false,
      model: ref({} as dynamicObj),
      fieldsDef: ref({} as dynamicObj),
      readOnlyfieldsDef: ref({} as dynamicObj),
      readonlyModel: ref({} as dynamicObj),
      usersList: ref([] as any),
      prev_assignee: ref(null),
      assign_user_error: ref(false),
      doc_logs: ref({} as any),
      pending_approval_doc_count: ref(0),
      next_record: ref(''),
      prev_record: ref(''),
      second_approval: ref(false),
      showNotification(message: string) {
        notify.info(message);
      },

      getDocAnnotations,
      showFontMenu: ref(true),
      showStampMenu: ref(false),
      selectColor: ref('#000000'),
      selectFont: ref('Helvetica'),
      fontlist: [
        'Helvetica',
        'Times New Roman',
        'Arimo',
        'Caladea',
        'Carlito',
        'Cousine',
        'Liberation Serif',
        'Arial',
      ],
      selectFontSize: ref(20),
      fontSizes: [] as any,
      showDoc: ref(false),

      selectedStamp: ref(''),
      // stamps: [
      //   'annotation/annotation_stamps/approved_stamp_de.svg',
      //   'annotation/annotation_stamps/rejected_stamp_de.svg',
      //   'annotation/annotation_stamps/approved_stamp_en.svg',
      //   'annotation/annotation_stamps/rejected_stamp_en.svg'
      // ],
      screenmode: ref('annotate'),
    };
  },
});
</script>

